package glitch

import data.glitch_lib

credential_fields := {
    "password", "pwd", "pass", "passwd", "user_password", "admin_password",
    "secret", "secret_key", "private_key", "api_key", "access_key", "auth_key",
    "token", "api_token", "auth_token", "credentials", "secrets", "creds", "auth",
    "cert", "certificate", "cert_pem", "cert_file", "ssl_cert", "tls_cert"
}

default_markers := {
    "default", "changeme", "password123", "admin", "root", "test", "demo", "example"
}

debug_markers := {"TODO", "FIXME", "HACK", "temp", "temporary", "debug", "dev", "local", "test"}

is_credential_field(name) {
    lower_field := lower(name)
    credential_fields[_] == lower_field
} else {
    lower_field := lower(name)
    contains(lower_field, credential_fields[_])
}

has_hardcoded_value(value) {
    value.ir_type == "String"
    count(value.value) > 0
    not isinstance(value.value, "VariableReference")
}

is_default_or_weak_value(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    default_markers[_] == lower_val
}

has_debug_comment(node) {
    walk(node, [_, n])
    n.ir_type == "Comment"
    lower_content := lower(n.content)
    contains(lower_content, debug_markers[_])
}

is_secure_reference(value) {
    value.ir_type == "FunctionCall"
    lower_name := lower(value.name)
    contains(lower_name, "secret")
} else {
    value.ir_type == "FunctionCall"
    lower_name := lower(value.name)
    contains(lower_name, "vault")
} else {
    value.ir_type == "FunctionCall"
    lower_name := lower(value.name)
    contains(lower_name, "data")
} else {
    value.ir_type == "VariableReference"
    lower_name := lower(value.value)
    contains(lower_name, "secret")
} else {
    value.ir_type == "VariableReference"
    lower_name := lower(value.value)
    contains(lower_name, "vault")
} else {
    value.ir_type == "VariableReference"
    lower_name := lower(value.value)
    contains(lower_name, "data")
}

contains_connection_string(value) {
    value.ir_type == "String"
    regex.match(".*://[^/]+:[^@]+@.*", value.value)
}

find_hashed_credential(hash) {
    hash.ir_type == "Hash"
    some key, val in hash.value
    key.ir_type == "String"
    is_credential_field(key.value)
    has_hardcoded_value(val)
    not is_secure_reference(val)
}

find_array_credential(arr) {
    arr.ir_type == "Array"
    some i
    elem := arr.value[i]
    find_hashed_credential(elem)
} else {
    arr.ir_type == "Array"
    some i
    elem := arr.value[i]
    cons(elem)
    elem.ir_type == "String"
    is_credential_field(elem.value)
}

find_nested_credential(value) {
    find_hashed_credential(value)
} else {
    find_array_credential(value)
} else {
    value.ir_type == "Hash"
    some _, val in value.value
    find_nested_credential(val)
} else {
    value.ir_type == "Array"
    some i
    elem := value.value[i]
    find_nested_credential(elem)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    unit := atomic_units[_]

    attrs := glitch_lib.all_attributes(unit)
    attr := attrs[_]

    is_credential_field(attr.name)
    has_hardcoded_value(attr.value)
    not is_secure_reference(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Credentials - Avoid hardcoding credentials in IaC scripts. Use secure secret management instead. (CWE-798)"
